/**
 * Node-agent client: talks to the small HTTPS service (node-agent/index.js)
 * that runs on every NON-PRIMARY node, giving the primary's worker a narrow,
 * token-authenticated way to touch that node's own NAT table and cloud-init
 * snippet storage — the two host-level operations the worker cannot do
 * remotely any other way (see docs/DOCUMENTATION.md's "Multi-node synergy").
 *
 * TOKEN DIRECTION: the primary is the CALLER here (unlike telemetry tokens,
 * where a server/node calls INTO the primary). So the primary must be able to
 * present the token on every request, not just verify one it already
 * receives — it is stored encrypted (lib/crypto-box.ts, AUTH_SECRET-derived),
 * not hashed, on `Node.agentTokenEnc`. The agent's own side stores its copy
 * in a local root-only file on that node (never in this app's database) and
 * compares incoming requests against it with a constant-time check — see
 * node-agent/index.js.
 *
 * TRANSPORT: HTTPS with a self-signed cert (generated once at onboard time),
 * verified the same way this codebase already trusts a node's Proxmox API
 * (lib/proxmox.ts's `insecureAgent`, rejectUnauthorized: false) — encrypts the
 * wire without needing a CA-issued cert for a bare IP with no public DNS name.
 * A leaked token's blast radius is deliberately narrow: NAT rules and
 * cloud-init snippets for ONE node, never a shell, never the database.
 */
import { Agent, fetch as undiciFetch } from "undici";
import { randomBytes } from "node:crypto";
import { encryptSecret, decryptSecret } from "./crypto-box";
import { db } from "./db";
import type { NatRule } from "./nat-rules";

const insecureAgent = new Agent({ connect: { rejectUnauthorized: false } });

const REQUEST_TIMEOUT_MS = 15_000;

/** Generate a fresh raw agent token. Shown to the operator exactly once
 *  (the onboarding script prints it; the admin "Add node" form is where it's
 *  pasted in and immediately encrypted — never redisplayed after that). */
export function generateNodeAgentToken(): string {
  return randomBytes(32).toString("base64url");
}

/** Encrypt a raw token for storage on `Node.agentTokenEnc`. */
export function encryptNodeAgentToken(token: string): string {
  return encryptSecret(token);
}

/** The subset of `Node` every agent call needs. */
export type AgentNode = {
  id: string;
  name: string;
  publicIp: string;
  agentPort: number;
  agentTokenEnc: string | null;
};

/** Decrypt this node's agent token, or null if none is configured yet. */
export function nodeAgentToken(node: Pick<AgentNode, "agentTokenEnc">): string | null {
  return decryptSecret(node.agentTokenEnc);
}

