// READ-ONLY collector: GET calls only.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { pveFor } from "/tank/nxeon-wt-release2/lib/proxmox";

const url = process.env.DATABASE_URL!.split("?")[0];
const rows = JSON.parse(execFileSync("psql", [url, "-X", "-At", "-c",
  `select json_agg(n) from (select name,"pveNode","apiUrl","tokenId","tokenSecret" from "Node" order by "createdAt") n`]).toString().trim());
const out: any = {};
(async () => {
  for (const n of rows) {
    const o: any = { vms: [], lxc: [], storage: [], errors: [] };
    out[n.name] = o;
    try {
      const c = pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
      const g = async (p: string) => { try { return await c.get(p); } catch (e: any) { o.errors.push(p + ": " + e.message); return null; } };
      o.status = await g(`/nodes/${n.pveNode}/status`);
      const q = (await g(`/nodes/${n.pveNode}/qemu`)) || [];
      for (const v of q) {
        const cfg = await g(`/nodes/${n.pveNode}/qemu/${v.vmid}/config`);
        const rrd = await g(`/nodes/${n.pveNode}/qemu/${v.vmid}/rrddata?timeframe=week&cf=AVERAGE`);
        let agg: any = null;
        if (rrd && rrd.length) {
          const pts = rrd.filter((p: any) => p.cpu != null);
          const avg = (k: string) => pts.length ? pts.reduce((s: number, p: any) => s + (p[k] || 0), 0) / pts.length : null;
          const max = (k: string) => pts.length ? Math.max(...pts.map((p: any) => p[k] || 0)) : null;
          agg = { n: pts.length, cpuAvg: avg("cpu"), cpuMax: max("cpu"), memAvg: avg("mem"), memMax: max("mem"), netinAvg: avg("netin"), netoutAvg: avg("netout"), diskrAvg: avg("diskread"), diskwAvg: avg("diskwrite"), firstTs: rrd[0].time, lastTs: rrd[rrd.length-1].time };
        }
        o.vms.push({ ...v, cfg, rrd: agg });
      }
      const l = (await g(`/nodes/${n.pveNode}/lxc`)) || [];
      for (const v of l) {
        const cfg = await g(`/nodes/${n.pveNode}/lxc/${v.vmid}/config`);
        o.lxc.push({ ...v, cfg });
      }
      const sts = (await g(`/nodes/${n.pveNode}/storage`)) || [];
      for (const s of sts) {
        const content = s.active ? await g(`/nodes/${n.pveNode}/storage/${s.storage}/content`) : null;
        o.storage.push({ ...s, content });
      }
    } catch (e: any) { o.errors.push("fatal: " + e.message); }
  }
  writeFileSync(process.argv[2], JSON.stringify(out));
  console.log("done");
})();

