/**
 * Low-level call to a node's agent. Throws NodeAgentError with a message safe
 * to surface in worker logs (never includes the token).
 */
async function agentRequest(
  node: AgentNode,
  method: "GET" | "POST" | "DELETE",
  path: string,
  body?: unknown
): Promise<any> {
  const token = nodeAgentToken(node);
  if (!token) {
    throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
  }
  const url = `https://${node.publicIp}:${node.agentPort}${path}`;
  const doFetch = () =>
    undiciFetch(url, {
      method,
      headers: {
        Authorization: `Bearer ${token}`,
        ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
      },
      body: body !== undefined ? JSON.stringify(body) : undefined,
      dispatcher: insecureAgent,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
  let res: Awaited<ReturnType<typeof doFetch>>;
  try {
    res = await doFetch();
  } catch (e: any) {
    throw new NodeAgentError(`could not reach node-agent on "${node.name}" (${url}): ${e?.message ?? e}`, node.name);
  }
  const text = await res.text().catch(() => "");
  if (!res.ok) {
    throw new NodeAgentError(`node-agent on "${node.name}" returned ${res.status}: ${text.slice(0, 300)}`, node.name);
  }
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    throw new NodeAgentError(`node-agent on "${node.name}" returned a non-JSON response: ${text.slice(0, 200)}`, node.name);
  }
}

