import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { loadAgentNode, agentListChain, agentNeighbors } from "/tank/nxeon-wt-release2/lib/node-agent";

const url = process.env.DATABASE_URL!.split("?")[0];
const rows = JSON.parse(execFileSync("psql", [url, "-X", "-At", "-c",
