      o.chain = await agentListChain(n, r.natChain);
      o.neigh = await agentNeighbors(n);
    } catch (e: any) { o.err = e.message; }
  }
  writeFileSync(process.argv[2], JSON.stringify(out));
  console.log("ok");
})();

