export async function withServerSsh<T>(
  server: SftpServer,
  fn: (conn: Client) => Promise<T>
): Promise<T> {
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const privateKey = serverManagementKey(server);
  const password = serverRootPassword(server);
  if (!privateKey && !password) throw new Error("Server has no root password on record.");

  // Try the per-server management key first (see Server.sshManagementKeyEnc's
  // schema doc comment) — falls back to the password if there's no key on file
  // yet, or the key is present but the connect itself fails (e.g. a customer
  // deleted our line from their own authorized_keys). Only a CONNECT failure
  // triggers the fallback — once `fn` is running, its own errors propagate
  // normally rather than silently retrying the whole operation a second time.
  let conn: Client;
  if (privateKey) {
    try {
      conn = await connectOnce(target, { privateKey });
    } catch (e) {
      if (!password) throw e;
      conn = await connectOnce(target, { password });
    }
  } else {
    conn = await connectOnce(target, { password: password! });
  }

  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

/**
 * Detect the package manager on the far side and return the install prefix, or
 * throw if none is supported. Fixed strings only — no user input.
 */
 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
 * value and falling back to the legacy plaintext column for rows that predate
 * encryption. Every READ of a root password must go through this helper so both
 * shapes keep working transparently.
 */
export function serverRootPassword(
  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
): string | null {
  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
}

/**
 * Resolve a server's decrypted OpenSSH-format management PRIVATE key, if one has
 * been generated for it (see Server.sshManagementKeyEnc's schema doc comment).
 * Null for any server not yet provisioned/backfilled with one.
 */
export function serverManagementKey(
  server: { sshManagementKeyEnc?: string | null }
): string | null {
  return decryptSecret(server.sshManagementKeyEnc);
}

/** The minimal shape of a Server we need to open a connection. */
export type SftpServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  /** See Server.sshManagementKeyEnc's schema doc comment. Optional so every
   *  existing caller that doesn't select it keeps today's password-only path. */
  sshManagementKeyEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
  /** The server's own node — vmids/ports are per-node, so a NAT (non-dedicated-IP)
   *  server's real SSH host is THIS node's public IP, not necessarily the
   *  platform's env-configured primary. Optional so existing callers that don't
   *  select it keep today's exact fallback behavior (see connectionTarget). */
  node?: { publicIp: string } | null;
  /** See Server.guestSshPort's schema doc comment. Only meaningful on a
   *  dedicated-IP server — optional so a caller that doesn't select it keeps
   *  today's "assume port 22" behavior via connectionTarget's `?? 22`. */
  guestSshPort?: number | null;
};
 * dedicated IP -> :22, otherwise the server's OWN node's public IP : sshPort
 * (falling back to the platform's env-configured primary only when the
 * server genuinely has no node relation — e.g. not yet selected by an older
 * caller, or a row that predates multi-node). Getting this wrong for a
 * server on a non-primary node means dialing the WRONG physical host
 * entirely, not just a wrong port — verified live 2026-09-05 as the root
 * cause of an entire class of "control panel dead for node-2" bugs.
 */
export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp!.address : (server.node?.publicIp ?? process.env.PUBLIC_IP ?? "");
  const port = dedicated ? (server.guestSshPort ?? 22) : server.sshPort;
  if (!host || !port) return null;
  return { host, port };
}

/**
 * Open one SFTP connection: the per-server management key first, falling back to the root
 * password (see the long note on Server.sshManagementKeyEnc). A fresh client per attempt:
 * reusing one after a failed connect is not a state ssh2-sftp-client guarantees to recover from.
 */
async function connectSftp(
  target: { host: string; port: number },
  privateKey: string | null,
  password: string | null
): Promise<SftpClient> {
  if (privateKey) {
    const keyClient = new SftpClient();
    try {
      await keyClient.connect({
        host: target.host,
        port: target.port,
        username: "root",
        privateKey,
        readyTimeout: CONNECT_TIMEOUT_MS,
      });
      return keyClient;
    } catch (e) {
      try { await keyClient.end(); } catch { /* best effort */ }
      if (!password) throw e;
    }

